/*
 * prog22_snake_camel_convert
 *
 * Behaviour (as observed from the original binary):
 *
 *   prog22_snake_camel_convert <mode> <string>
 *
 *   <mode>   – either "to_camel" or "to_snake"
 *   <string> – the text to be converted
 *
 *   * If the argument count is wrong the program prints:
 *
 *         USAGE
 *
 *   * If the mode is not one of the two supported strings it prints:
 *
 *         INVALID_MODE
 *
 *   * Otherwise it converts the supplied string and prints the result.
 *
 * Conversion rules (derived from the decompiled, heavily‑obfuscated code):
 *
 *   to_camel : snake_case → camelCase
 *              – underscores are removed
 *              – the first character after each underscore is capitalised
 *
 *   to_snake : camelCase → snake_case
 *              – an underscore is inserted before every upper‑case character
 *                (except the very first character)
 *              – all characters are emitted in lower case
 *
 * The original binary limited the output buffer to 0x400 bytes (1024 bytes,
 * including the terminating NUL).  The implementation below respects the same
 * limit.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024   /* 0x400 bytes – same limit as the original binary */

static char out_buf[OUT_BUF_SIZE];

/* Convert a snake_case string to camelCase. */
static void to_camel(const char *src)
{
    size_t out_idx = 0;
    int capitalize_next = 0;          /* set after an '_' is seen */

    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        char c = src[i];

        if (c == '_') {
            capitalize_next = 1;      /* next alphabetic character will be upper */
            continue;                 /* '_' itself is not copied */
        }

        if (capitalize_next && islower((unsigned char)c)) {
            c = (char)toupper((unsigned char)c);
        }
        /* If the flag is set but the character is not a lower‑case letter
           (e.g. a digit) we simply copy it unchanged – this matches the
           behaviour of the original obfuscated code. */
        capitalize_next = 0;

        out_buf[out_idx++] = c;
    }
    out_buf[out_idx] = '\0';
}

/* Convert a camelCase string to snake_case. */
static void to_snake(const char *src)
{
    size_t out_idx = 0;
    int first_char = 1;               /* true for the very first character */

    for (size_t i = 0; src[i] != '\0' && out_idx + 1 < OUT_BUF_SIZE; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (isupper(c)) {
            if (!first_char) {
                out_buf[out_idx++] = '_';
            }
            c = (unsigned char)tolower(c);
        }
        out_buf[out_idx++] = (char)c;
        first_char = 0;
    }
    out_buf[out_idx] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];

    if (strcmp(mode, "to_camel") == 0) {
        to_camel(input);
        puts(out_buf);
    } else if (strcmp(mode, "to_snake") == 0) {
        to_snake(input);
        puts(out_buf);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
